"""Fashion-style PUBLIC-DATABASE items, part 8: cultural-dress, workwear-style.
12+12+10=34 each. Respectful, educational treatment of cultural garments - no religious framing.
Property of Justin Addam Higgins (JAH)."""
from music_db import T, list_demo
from fashion_db7b import ITEMS
from fashion_db1 import _mk

def X(F, title, g, s1, s2, pts, keys, ca, cb):
    return T(title, g, [s1, s2], pts, keys, [ca, cb],
             demo=list_demo(title, [p[:30] for p in pts] + ['The done'], title + ':'))

